<script>
'use strict';
/* ============================================================
   CHIP-8 interpreter
   ============================================================ */
const MEM_SIZE   = 4096;
const PROG_START = 0x200;
const FONT_START = 0x050;
const STACK_SIZE = 16;

const FONTSET = [
  0xF0,0x90,0x90,0x90,0xF0, // 0
  0x20,0x60,0x20,0x20,0x70, // 1
  0xF0,0x10,0xF0,0x80,0xF0, // 2
  0xF0,0x10,0xF0,0x10,0xF0, // 3
  0x90,0x90,0xF0,0x10,0x10, // 4
  0xF0,0x80,0xF0,0x10,0xF0, // 5
  0xF0,0x80,0xF0,0x90,0xF0, // 6
  0xF0,0x10,0x20,0x40,0x40, // 7
  0xF0,0x90,0xF0,0x90,0xF0, // 8
  0xF0,0x90,0xF0,0x10,0xF0, // 9
  0xF0,0x90,0xF0,0x90,0x90, // A
  0xE0,0x90,0xE0,0x90,0xE0, // B
  0xF0,0x80,0x80,0x80,0xF0, // C
  0xE0,0x90,0x90,0x90,0xE0, // D
  0xF0,0x80,0xF0,0x80,0xF0, // E
  0xF0,0x80,0xF0,0x80,0x80  // F
];

class Chip8 {
  constructor(){
    this.mem   = new Uint8Array(MEM_SIZE);
    this.V     = new Uint8Array(16);
    this.I     = 0;
    this.pc    = PROG_START;
    this.stack = new Uint16Array(STACK_SIZE);
    this.sp    = 0;
    this.dt    = 0;
    this.st    = 0;
    this.gfx   = new Uint8Array(64 * 32);
    this.keys  = new Uint8Array(16);
    this.keyWait = -1;      // index of key Fx0A is waiting on (-1 none)
    this.running = false;
    this.halted  = false;
    this.opCount = 0;
    this.lastPC  = PROG_START;
    this.lastInstr = null;  // {word, text}
    this.onSound = null;
    this.onWarn = null;
    for (let i = 0; i < FONTSET.length; i++) this.mem[FONT_START + i] = FONTSET[i];
  }

  loadROM(bytes, name){
    if (PROG_START + bytes.length > MEM_SIZE)
      throw new Error('ROM too big: ' + bytes.length + ' bytes (max ' + (MEM_SIZE - PROG_START) + ')');
    this.reset();
    for (let i = 0; i < bytes.length; i++) this.mem[PROG_START + i] = bytes[i];
    this.romName = name || 'loaded';
    this.romEnd  = PROG_START + bytes.length;
  }

  reset(){
    this.V.fill(0); this.I = 0; this.pc = PROG_START;
    this.sp = 0; this.dt = 0; this.st = 0;
    this.gfx.fill(0); this.keyWait = -1;
    this.running = false; this.halted = false;
    this.opCount = 0; this.lastInstr = null;
  }

  keyDown(n){
    this.keys[n] = 1;
    if (this.keyWait >= 0){ this.V[this.keyWait] = n; this.keyWait = -1; }
  }
  keyUp(n){ this.keys[n] = 0; }

  /* ---- timers: call at 60 Hz ---- */
  tickTimers(){
    if (this.dt > 0) this.dt--;
    if (this.st > 0){
      this.st--;
      if (this.st === 0 && this.onSound) this.onSound(false);
      else if (this.st > 0 && this.onSound) this.onSound(true);
    }
  }

  /* ---- one instruction ---- */
  step(){
    if (this.halted) return false;
    if (this.pc + 1 >= MEM_SIZE){ this.halt('PC out of range: 0x' + this.pc.toString(16)); return false; }
    const mem = this.mem;
    const word = (mem[this.pc] << 8) | mem[this.pc + 1];
    const hi = word >> 8, lo = word & 0xFF;
    const x = (word >> 8) & 0xF, y = (word >> 4) & 0xF, n = word & 0xF;
    const kk = lo, nnn = word & 0xFFF;
    const V = this.V;
    let text = '';
    let jumped = false;

    switch (hi){
      case 0x0:
        if (n === 0xE0){ this.gfx.fill(0); text = 'CLS'; }
        else if (n === 0xEE){
          if (this.sp === 0){ this.halt('RET with empty stack at 0x' + this.pc.toString(16)); return false; }
          this.pc = this.stack[--this.sp]; text = 'RET'; jumped = true;
        } else return this.bad(word);
        break;
      case 0x1: this.pc = nnn; text = 'JP $' + hex3(nnn); jumped = true; break;
      case 0x2:
        if (this.sp >= STACK_SIZE){ this.halt('Stack overflow at 0x' + this.pc.toString(16)); return false; }
        this.stack[this.sp++] = this.pc; this.pc = nnn;
        text = 'CALL $' + hex3(nnn); jumped = true; break;
      case 0x3: if (V[x] === kk){ this.pc += 2; } text = 'SE V' + hx(x) + ', $' + hex2(kk); break;
      case 0x4: if (V[x] !== kk){ this.pc += 2; } text = 'SNE V' + hx(x) + ', $' + hex2(kk); break;
      case 0x5: if (n === 0 && V[x] === V[y]){ this.pc += 2; } text = 'SE V' + hx(x) + ', V' + hx(y); break;
      case 0x6: V[x] = kk; text = 'LD V' + hx(x) + ', $' + hex2(kk); break;
      case 0x7: V[x] = (V[x] + kk) & 0xFF; text = 'ADD V' + hx(x) + ', $' + hex2(kk); break;
      case 0x8:
        switch (n){
          case 0: V[x] = V[y];                 text = 'LD V' + hx(x) + ', V' + hx(y); break;
          case 1: V[x] |= V[y];                text = 'OR V' + hx(x) + ', V' + hx(y); break;
          case 2: V[x] &= V[y];                text = 'AND V' + hx(x) + ', V' + hx(y); break;
          case 3: V[x] ^= V[y];                text = 'XOR V' + hx(x) + ', V' + hx(y); break;
          case 4: { const s = V[x] + V[y]; V[x] = s & 0xFF; V[0xF] = s > 0xFF ? 1 : 0;
                    text = 'ADD V' + hx(x) + ', V' + hx(y); break; }
          case 5: { const b = V[x] >= V[y] ? 1 : 0; V[x] = (V[x] - V[y]) & 0xFF; V[0xF] = b;
                    text = 'SUB V' + hx(x) + ', V' + hx(y); break; }
          case 6: { const c = (V[x] >> 7) & 1; V[x] = (V[x] >> 1) & 0xFF; V[0xF] = c;
                    text = 'SHR V' + hx(x) + ' (V' + hx(y) + ')'; break; }
          case 7: { const b = V[y] >= V[x] ? 1 : 0; V[x] = (V[y] - V[x]) & 0xFF; V[0xF] = b;
                    text = 'SUBN V' + hx(x) + ', V' + hx(y); break; }
          case 8: { const c = (V[x] >> 7) & 1; V[x] = (V[x] << 1) & 0xFF; V[0xF] = c;
                    text = 'SHL V' + hx(x) + ' (V' + hx(y) + ')'; break; }
          default: return this.bad(word);
        }
        break;
      case 0x9: if (n === 0 && V[x] !== V[y]){ this.pc += 2; } text = 'SNE V' + hx(x) + ', V' + hx(y); break;
      case 0xA: this.I = nnn; text = 'LD I, $' + hex3(nnn); break;
      case 0xB: this.pc = (nnn + V[0]) & 0xFFF; text = 'JP V0 + $' + hex3(nnn); jumped = true; break;
      case 0xC: V[x] = (Math.floor(Math.random() * 256)) & kk; text = 'RND V' + hx(x) + ' & $' + hex2(kk); break;
      case 0xD: {
        const sx = V[x] & 63, sy = V[y] & 31;
        let collision = 0;
        for (let row = 0; row < n; row++){
          const bits = mem[(this.I + row) & 0xFFF];
          const py = (sy + row) & 31;
          for (let col = 0; col < 8; col++){
            if ((bits >> (7 - col)) & 1){
              const px = (sx + col) & 63;
              const idx = py * 64 + px;
              if (this.gfx[idx]) collision = 1;
              this.gfx[idx] ^= 1;
            }
          }
        }
        V[0xF] = collision;
        text = 'DRW V' + hx(x) + ',V' + hx(y) + ',' + n;
        break;
      }
      case 0xE:
        if (kk === 0x9E){ if (this.keys[V[x] & 0xF]){ this.pc += 2; } text = 'SKP V' + hx(x); }
        else if (kk === 0xA1){ if (!this.keys[V[x] & 0xF]){ this.pc += 2; } text = 'SKNP V' + hx(x); }
        else return this.bad(word);
        break;
      case 0xF:
        switch (kk){
          case 0x07: V[x] = this.dt; text = 'LD V' + hx(x) + ', DT'; break;
          case 0x0A: {
            let k = -1;
            for (let i = 0; i < 16; i++) if (this.keys[i]){ k = i; break; }
            if (k < 0){ this.keyWait = x; text = 'LD V' + hx(x) + ', K (waiting)'; return this.finish(word, text, true); }
            V[x] = k; text = 'LD V' + hx(x) + ', K';
            break;
          }
          case 0x15: this.dt = V[x]; text = 'LD DT, V' + hx(x); break;
